function autoDigest(ctx, board) {
  const seen = new Set();

  guarded(() =>
    ctx.systemPrompt.context({
      name: "deja:project",
      order: 110,
      interpolate: false,
      text: (assembly) => {
        const agent = assembly && assembly.agent;
        if (!agent) return "";
        const sid = sessionId(agent);
        if (sid && seen.has(sid)) return "";
        if (sid) seen.add(sid);
        return inert(askHook(
